import ghidra.app.emulator.EmulatorHelper;
import java.io.PrintWriter;
public class ZNativeAmbientWaterOracle extends ZNativeAmbientAnimationOracle{
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){EmulatorHelper e=new EmulatorHelper(currentProgram);try{e.setBreakpoint(toAddr(0x404af0));for(int s=0;s<256;s++){byte[]pool=new byte[7200];for(int i=0;i<pool.length;i++)pool[i]=(byte)(i*17+s);e.writeMemory(toAddr(P),pool);int free=new int[]{0,1,149,150}[s&3];for(int i=0;i<150;i++)put(e,P+i*48,2,i<free?100+i:-1);execute(e,0x41dcc0,346+s%9,420+s/9%9);out.println("{\"kind\":\"waterInit\",\"scenario\":"+s+",\"hash\":"+hash(e.readMemory(toAddr(P),7200))+"}");}for(int s=0;s<64;s++){e.writeMemory(toAddr(P),new byte[7200]);e.writeMemory(toAddr(A),new byte[2400]);for(int i=0;i<150;i++)put(e,P+i*48,2,-1);execute(e,0x41dcc0,346+s,420-s);put(e,0x622cb8,2,s%3*12);put(e,0x622cba,2,s%5*8);for(int tick=0;tick<24;tick++){put(e,0x62b3a4,4,D);put(e,0x62d5d8,4,A);execute(e,0x41d6a0,0,0);int n=(int)(read(e,0x62b3a4,4)-D);out.println("{\"kind\":\"waterTick\",\"scenario\":"+(s*24+tick)+",\"hash\":"+hash(e.readMemory(toAddr(P),7200))+",\"drawBytes\":"+n+",\"drawHash\":"+(n==0?2166136261L:hash(e.readMemory(toAddr(D),n)))+"}");}}}finally{e.dispose();}}}
}
